#!/bin/bash
# Print the three most frequent first-field tokens in access.log,
# most frequent first; ties broken by first appearance in the log.
awk '
{
    ip = $1
    count[ip]++
    if (!(ip in seen)) {
        seen[ip] = ++order
        order_list[order] = ip
    }
}
END {
    # Stable sort by count descending, then by first appearance.
    for (i = 1; i <= order; i++) {
        a[i] = order_list[i]
    }
    # Simple insertion sort; log is small.
    for (i = 2; i <= order; i++) {
        key = a[i]
        j = i - 1
        while (j >= 1 && (count[a[j]] < count[key] || (count[a[j]] == count[key] && seen[a[j]] > seen[key]))) {
            a[j+1] = a[j]
            j--
        }
        a[j+1] = key
    }
    n = order < 3 ? order : 3
    for (i = 1; i <= n; i++) print a[i]
}
' access.log
